import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { APEX_ORIGIN, MCP_RESOURCE_URI } from "@pocketcircle/domain/origins";

/**
 * Build-time check: Google branding crawlers read static HTML (no JS). Fail the
 * build if the SPA shell or prerendered legal pages lose required copy.
 *
 * The crawl directives are not among them, and used to be: `robots.txt` and
 * `sitemap.xml` were generated here and are now generated by `apps/site`, which
 * serves the apex they describe (#411). `apps/site/scripts/assert-site-html.mjs` and
 * the deploy's "Verify marketing Site" step hold them there. This file still checks
 * the legal documents on the app origin, because the app's own chrome links to them
 * and a signed-in User is still on the app — the apex copy is the one Google reads,
 * and `legal-documents.test.tsx` is what holds the two sets of copy identical.
 */
const clientDir = join(dirname(fileURLToPath(import.meta.url)), "../build/client");

function requireHtml(relativePath, needles) {
  const path = join(clientDir, relativePath);
  if (!existsSync(path)) {
    throw new Error(`Missing branding HTML: ${relativePath}`);
  }
  const html = readFileSync(path, "utf8");
  for (const needle of needles) {
    if (!html.includes(needle)) {
      throw new Error(`${relativePath} missing ${JSON.stringify(needle)}`);
    }
  }
}

if (existsSync(join(clientDir, "__spa-fallback.html"))) {
  throw new Error(
    "Unexpected __spa-fallback.html — prerendering `/` breaks Cloudflare SPA fallback (always uses /index.html). Keep `/` off the prerender list.",
  );
}

requireHtml("index.html", [
  "PocketCircle",
  "PocketCircle helps you track spending together in shared Circles",
  "Privacy Policy",
  // The apex in full, not a relative path: the policies are the marketing Site's
  // documents and ADR 0035 moves this app to its own subdomain, where a relative
  // `/privacy` would be a redirect rather than the policy Google reads.
  `href="${APEX_ORIGIN}/privacy"`,
  "Continue with Google",
]);

requireHtml("privacy/index.html", ["Privacy Policy", "Information we collect"]);
requireHtml("terms/index.html", ["Terms &amp; Conditions"]);
requireHtml("support/index.html", ["Support", MCP_RESOURCE_URI]);
requireHtml("whats-new/index.html", ["What&#x27;s new"]);

console.log("Branding HTML ok (index + privacy + terms + support + whats-new).");
